"\"<?php\n// Script untuk menambahkan kolom Nilai Akhir Skripsi\n\n\$content = file_get_contents('src/views/scores/submit.php');\n\n// Temukan bagian thead dan tambahkan kolom\n\$pattern = '/(<thead>\\\\s*<tr>\\\\s*<th>NIM<\\\\/th>\\\\s*<th>Nama<\\\\/th>\\\\s*(?:<\\\\?php foreach \\\\(\\\\\\$availableStages as \\\\\\$stageCode => \\\\\\$stageLabel\\\\): \\\\?>\\\\s*<th><\\\\?= htmlspecialchars\\\\(\\\\\\$stageLabel\\\\) \\\\?><\\\\/th>\\\\s*<\\\\?php endforeach; \\\\?>\\\\s*)<\\\\/tr>\\\\s*<\\\\/thead>)/';\n\n\$replacement = '<thead>\\\\n                                <tr>\\\\n                                    <th>NIM</th>\\\\n                                    <th>Nama</th>\\\\n                                    <?php foreach (\\$availableStages as \\$stageCode => \\$stageLabel): ?>\\\\n                                        <th><?= htmlspecialchars(\\$stageLabel) ?></th>\\\\n                                    <?php endforeach; ?>\\\\n                                    <th>Nilai Akhir Skripsi</th>\\\\n                                </tr>\\\\n                            </thead>';\n\n\$content = preg_replace(\$pattern, \$replacement, \$content);\n\n// Simpan perubahan\nfile_put_contents('src/views/scores/submit.php', \$content);\n\necho \"Kolom Nilai Akhir Skripsi berhasil ditambahkan!\\\\n\";\n?>\""